//! unplugin-vue-router: the file-based routes under `src/pages`. `vue-router` 5 includes the plugin, so a package that
//! depends on `vue-router` gets the routes when a declaration file generated by it exists.

use crate::plugin::{Enabler, Plugin, PluginContext, PluginInput, PluginSpec};
use crate::plugins::vue::generated_declarations;

/// The `unplugin-vue-router` plugin.
pub struct UnpluginVueRouter;

const ROUTES: &str = "src/pages/**/*.{vue,md}";

static SPEC: PluginSpec = PluginSpec {
    id: "unplugin-vue-router",
    enablers: &[
        Enabler::Dependency("unplugin-vue-router"),
        Enabler::Dependency("vue-router"),
    ],
    ..PluginSpec::DEFAULT
};

impl Plugin for UnpluginVueRouter {
    fn spec(&self) -> &'static PluginSpec {
        &SPEC
    }

    fn reads_config(&self) -> bool {
        false
    }

    fn resolve_workspace(&self, cx: &PluginContext<'_>) -> Vec<PluginInput> {
        let routed = cx.has_dependency_in_ancestors("unplugin-vue-router")
            || !generated_declarations(cx, "Generated by vue-router").is_empty();
        if routed {
            vec![PluginInput::ProductionEntry(ROUTES.to_owned())]
        } else {
            Vec::new()
        }
    }
}
